    42	/// Complete page metadata together with the retained resident mapping.
    43	///
    44	/// The bytes in `page.memory` may have been discarded by the OS while this
    45	/// value is in compressed state. They must not be read until `restore` has
    46	/// successfully decoded the page.
    47	page: TerminalPage,
    48	
    49	/// Exact raw LZ4 block for `page.memory`.
    50	encoded: []u8,
    51	
    52	/// Allocator which owns `encoded`.
    53	///
    54	/// The allocator's backing state must outlive this compressed page. Storing
    55	/// the allocator here lets a PageList node restore and discard its compressed
    56	/// state without needing a reference back to the PageList.
    57	alloc: Allocator,
    58	
    59	/// Return the largest scratch buffer that can produce a useful compressed
    60	/// representation for `raw_len` bytes.
    61	///
    62	/// This is deliberately smaller than the general LZ4 compression bound. The
    63	/// compressed representation includes an additional slice compared to a
    64	/// resident terminal page, so an encoded block which fills more than this
    65	/// buffer cannot reduce resident memory. Limiting the output here lets a
    66	/// PageList borrow a standard page-pool item as scratch instead of retaining a
    67	/// larger, compression-bound allocation.
    68	///
    69	/// Callers are expected to reuse the scratch memory when practical. The
    70	/// scratch buffer and hash table are never retained by this type.
    71	pub fn requiredScratch(raw_len: usize) lz4.CompressError!usize {
